<div class="form-grid"><x-field name="title" label="Quiz title" :value="$record->title" :required="true" maxlength="150"/><x-field name="category_id" label="Question-bank category" type="select" :value="$record->category_id" :options="[''=>'Select a category']+$categories->all()" :required="true"/></div><x-field name="description" label="Description" type="textarea" :value="$record->description" rows="3" maxlength="4000"/>
<div class="form-section-label">Assessment rules</div><div class="form-grid four"><x-field name="question_count" label="Questions per attempt" type="number" :value="$record->question_count" min="1" max="200" :required="true"/><x-field name="duration_minutes" label="Duration (minutes)" type="number" :value="$record->duration_minutes" min="1" max="240" :required="true"/><x-field name="pass_percentage" label="Pass mark (%)" type="number" :value="$record->pass_percentage" min="1" max="100" :required="true"/><x-field name="max_attempts" label="Attempt limit" type="number" :value="$record->max_attempts" min="1" max="100" :required="true"/></div>
<div class="toggle-grid"><x-toggle name="shuffle_questions" label="Randomize questions" :value="$record->shuffle_questions" help="Sample active questions from this category for each new attempt."/><x-toggle name="shuffle_options" label="Shuffle answer choices" :value="$record->shuffle_options" help="Keep the answer key correct while changing option order."/><x-toggle name="review_answers" label="Allow answer review" :value="$record->review_answers" help="Show correct answers and explanations after submission."/><x-toggle name="is_published" label="Publish this quiz" :value="$record->is_published" help="Publishing requires enough active questions in the category."/></div>
<div class="form-section-label">Who can take this quiz?</div><x-field name="access_mode" label="Access" type="select" :value="$record->access_mode" :options="['all'=>'All learners','assigned'=>'Selected learners only']"/>
<x-field name="user_ids[]" label="Selected learners" type="select" :multiple="true" :value="$record->exists ? $record->users->pluck('id')->all() : []" :options="$learners->mapWithKeys(fn($u)=>[$u->id=>$u->name.' ('.$u->email.')'])->all()" size="6" help="Used only for selected-learner access. Hold Ctrl on Windows or Command on macOS to select several people."/>
<div class="notice">Every question is worth one mark. Incorrect and unanswered choices receive zero marks. Changes apply only to new attempts.</div>
